        int N = Integer.parseInt(br.readLine().trim());

        int[] start = new int[101];
        boolean[] pending = new boolean[101];
        boolean[] seen = new boolean[101];
        long[] total = new long[101];

        int time = 0;
        int gap = 1;

        for (int i = 0; i < N; i++) {
            String[] parts = br.readLine().trim().split("\\s+");
            char type = parts[0].charAt(0);
            int x = Integer.parseInt(parts[1]);

            if (type == 'T') {
                gap = x;
            } else {
                time += gap;
                seen[x] = true;

                if (type == 'R') {
                    pending[x] = true;
                    start[x] = time;
                } else {
                    if (pending[x]) {
                        total[x] += time - start[x];
                        pending[x] = false;
                    }
                }

                gap = 1;
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 1; i <= 100; i++) {
            if (seen[i]) {
                sb.append(i).append(' ');
                if (pending[i]) {
                    sb.append("-1");
                } else {
                    sb.append(total[i]);
                }
                sb.append('\n');
            }
        }

